// the möbius transformation
// z -> (az+b)/(cz-d); where a,b,c,d are complex numbers and z will be the uv-vector
// (az+b)/(cz-d) = a/c + mu/(cz+d), with mu = (bc-ad)/c
// so a/c and mu can be calculated outside of the shader

//before inversion

scale = 1;
angle = time*.2;
translation_x = 0;
translation_y = 0.12;

a_r = cos(angle)*scale;
a_i = sin(angle)*scale;
b_r = translation_x;
b_i = translation_y;

//complex inverted
scale = 1;
angle = sin(time*0.1337)*0.3;
translation_u = 0;
translation_v = -0.2;

// c
q15 = cos(angle)*scale;
q16 = sin(angle)*scale;

// d
q17 = translation_u;
q18 = translation_v;

// c^(-1)
c_inv_r = q15/(q15*q15+q16*q16);
c_inv_i = q16/(q15*q15+q16*q16);

// a*c^(-1)
q11 = (a_r*c_inv_r - a_i*c_inv_i);
q12 = (a_r*c_inv_i - a_i*c_inv_r);

// (bc-ad)
bcad_r = (b_r*q15 - b_i*q16)-(a_r*q17-a_i*q18);
bcad_i = (b_r*q16 - b_i*q15)-(a_r*q18-a_i*q17);

// mu*c^(-1)
q13 = bcad_r*c_inv_r - bcad_i*c_inv_i;
q14 = bcad_r*c_inv_i - bcad_i*c_inv_r;

